MILLION = Decimal(1_000_000)


@dataclass(frozen=True)
class Model:
    name: str
    input_rate: Decimal | None
    output_rate: Decimal | None

    @property
    def comparable(self):
        return self.input_rate is not None and self.output_rate is not None


def number(text, label, whole=False):
    try:
        value = Decimal(text.strip())
        if value.is_finite() and 0 <= value <= Decimal("1e15"):
            if not whole or value == value.to_integral_value():
                return value
    except InvalidOperation:
        pass
    kind = "whole number" if whole else "number"
    raise ValueError(f"{label} must be a non-negative {kind} up to 10^15.")


def estimate(models, requests, input_tokens, output_tokens, days):
    def daily(model):
        return requests * (
            input_tokens * model.input_rate + output_tokens * model.output_rate
        ) / MILLION

    rows = []
    for key, model in models.items():
        cost = daily(model)
        rows.append((key, model.name, cost, cost * days, cost * 365))
    return sorted(rows, key=lambda row: row[2])


def load_catalog():
    return {
        key: Model(name, input_rate, output_rate)
        for key, name, input_rate, output_rate in ((row["id"], f'{row["name"]} ({row["provider"]})', row["inputPrice"], row["outputPrice"]) for row in snapshot["models"])
    }


