def render_resources(key, row):
    name, provider = row["name"], row["provider"]
    blog_query = urlencode({"q": f'"{name}" {provider} technical blog tutorial'})
    project_query = urlencode({"q": f'"{name}" in:readme', "type": "repositories"})
    resources = MODEL_RESOURCES.get(key, ()) + (
        ("Web search", f"Find technical blogs for {name}", f"https://www.google.com/search?{blog_query}"),
        ("GitHub search", f"Find projects mentioning {name}", f"https://github.com/search?{project_query}"),
    )
    resource_list = element("detail-resource-list")
    resource_list.replaceChildren()
    for kind, title, url in resources:
        item = document.createElement("li")
        link = document.createElement("a")
        link.href = url
        link.target = "_blank"
        link.rel = "noopener noreferrer"
        link.textContent = f"{title} · {kind}"
        item.appendChild(link)
        resource_list.appendChild(item)


def render_details(event=None):
    key = value("detail-model")
    row = detail_entries.get(key)
    element("detail-card").hidden = row is None
    element("detail-empty").hidden = row is not None
    if row is None:
        return
    notes = shortlist_details.get(key, {})
    element("detail-title").textContent = row["name"]
    identity = [row["provider"], row["category"]]
    if "rateUnit" not in row:
        identity.append(key)
    element("detail-id").textContent = " · ".join(identity)
    usage, usage_url = APPLICATIONS.get(key, ("No verified public application example is listed for this model.", ""))
    element("detail-usage").textContent = usage
    element("detail-usage-source").href = usage_url or "#"
    element("detail-usage-source").hidden = not usage_url
    element("detail-use").textContent = combine_details(row["useCase"], notes.get("useCase")) or "No use cases listed in the workbook."
    element("detail-domain").textContent = combine_details(row["domain"], notes.get("domain")) or "No domains listed in the workbook."
    fit = notes.get("fit")
    element("detail-fit").textContent = fit or ""
    element("detail-fit").hidden = not fit
    parameters = notes.get("parameters") or row.get("parameters")
    element("detail-parameters").textContent = parameters or ""
    element("detail-parameters-group").hidden = not parameters
    rates = row.get("documentedRate") or row.get("rateUnit")
    if not rates:
        rates = (
            f'{money(row["inputPrice"])} input · {money(row["outputPrice"])} output per million tokens'
            if row["inputPrice"] is not None or row["outputPrice"] is not None
            else "Comparable token pricing is unavailable in the workbook."
        )
    element("detail-rates").textContent = rates
    element("detail-basis").textContent = row.get("basis") or ""
    pricing_note = notes.get("pricing")
    element("detail-pricing-note").textContent = pricing_note or ""
    element("detail-pricing-note").hidden = not pricing_note
    source = row["source"] or notes.get("source")
    element("detail-source").href = source or "#"
    element("detail-source").hidden = not source
    render_resources(key, row)


