def render_leaders(event=None):
    category = value("leader-category")
    matching = [
        row for row in comparison_rows
        if not category or metadata.get(row[0], {}).get("category") == category
    ]
    for mode in ("price", "fit"):
        element(f"leader-{mode}-empty").hidden = bool(matching)
        element(f"leader-{mode}-table").hidden = not matching
    price_body = element("leader-rows")
    price_body.replaceChildren()
    rank, previous = 0, None
    for position, (key, name, _daily, monthly, *_) in enumerate(matching, start=1):
        if monthly != previous:
            rank, previous = position, monthly
        model = catalog[key]
        info = metadata.get(key, {})
        row = document.createElement("tr")
        for field in (str(rank), name, info.get("provider", "Custom"), money(model.input_rate), money(model.output_rate), f"${monthly:,.2f}"):
            cell(row, field)
        add_leader_source(row, info.get("source"))
        price_body.appendChild(row)

    fit_body = element("leader-job-rows")
    fit_body.replaceChildren()
    for key, name, *_ in sorted(matching, key=lambda row: (row[0] not in shortlist_details, row[1].casefold())):
        info = metadata.get(key, {})
        notes = shortlist_details.get(key, {})
        row = document.createElement("tr")
        cell(row, name)
        cell(row, notes.get("fit") or "—")
        cell(row, combine_details(info.get("useCase"), notes.get("useCase")) or "—")
        cell(row, combine_details(info.get("domain"), notes.get("domain")) or "—")
        add_leader_source(row, notes.get("source") or info.get("source"))
        fit_body.appendChild(row)


def add_leader_source(row, url):
    if url:
        source_cell(row, url)
    else:
        cell(row, "—")


