def infer_advisor_task(query):
    matches = [key for key, task in ADVISOR_TASKS.items() if re.search(task[1], query, re.I)]
    if "video" in matches and re.search(r"edit|footage|highlight|clips?", query, re.I):
        return "video"
    if "clinical" in matches and "coding-notes" not in matches:
        return "clinical"
    return next(iter(matches), "")


def clear_advisor_results(event=None):
    element("advisor-results").hidden = True


def advisor_message(message):
    target = element("advisor-status")
    target.textContent = message
    target.hidden = not message


def reset_advisor(event=None):
    element("advisor-requirements").hidden = True
    clear_advisor_results()
    advisor_message("")


def recognize_use_case(event):
    event.preventDefault()
    query = value("advisor-query").strip()
    if not query:
        reset_advisor()
        advisor_message("Describe what you want the model to do.")
        return
    key = infer_advisor_task(query)
    target = element("advisor-task")
    target.replaceChildren()
    option(target, "", "Choose the required output")
    for task_key, task in ADVISOR_TASKS.items():
        option(target, task_key, task[0])
    target.value = key or "custom-output"
    element("advisor-detail").value = "" if key else query
    for identifier in ("advisor-followup", "advisor-video-mode", "advisor-edit-goal"):
        element(identifier).value = ""
    element("advisor-volume").value = ""
    provider = element("advisor-provider")
    preferred = provider.value or ""
    if not preferred and re.search(r"\b(aws|bedrock|amazon)\b", query, re.I):
        preferred = "amazon"
    provider.replaceChildren()
    option(provider, "", "Any provider")
    providers = {row["provider"].casefold() for row in metadata.values()}
    providers.update(item["company"].casefold() for item in snapshot["media"])
    providers.update(("descript", "runway", "opusclip"))
    for name in sorted(providers | {"amazon"}):
        option(provider, name, "Amazon / AWS" if name == "amazon" else name)
    provider.value = preferred
    element("advisor-requirements").hidden = False
    configure_advisor()
    advisor_message(
        f"Detected: {ADVISOR_TASKS[key][0]}. Confirm the required output and workload."
        if key else "Describe the output in your own words to search the catalog."
    )
    (target if key else element("advisor-detail")).focus()


def advisor_task():
    selected_task = value("advisor-task")
    if selected_task != "custom-output":
        return selected_task
    details = value("advisor-detail").strip()
    return infer_advisor_task(details) or selected_task


def configure_advisor(event=None):
    clear_advisor_results()
    if event is not None:
        advisor_message("")
        if event.target.id in ("advisor-task", "advisor-video-mode"):
            element("advisor-followup").value = ""
            element("advisor-volume").value = ""
        if event.target.id == "advisor-task":
            element("advisor-video-mode").value = ""
            element("advisor-edit-goal").value = ""
    is_custom = value("advisor-task") == "custom-output"
    element("advisor-detail").required = is_custom
    element("advisor-detail-caption").textContent = (
        "What output do you need?" if is_custom else "More about your requirement (optional)"
    )
    key = advisor_task()
    mode = value("advisor-video-mode") if key == "video" else ""
    ask_followup = bool(key) and (key != "video" or mode == "generate")
    if ask_followup:
        caption, example = ADVISOR_FOLLOWUPS[key]
        element("advisor-followup-caption").textContent = caption
        element("advisor-followup").placeholder = example
    for name, visible in (("video-mode", key == "video"), ("edit-goal", mode == "edit"), ("followup", ask_followup)):
        element(f"advisor-{name}-label").hidden = not visible
        field = element(f"advisor-{name}")
        field.disabled = not visible
        field.required = visible
    units = ADVISOR_TASKS[key][2] if key and (key != "video" or mode == "generate") else ""
    element("advisor-budget-label").hidden = key == "video" and mode != "generate"
    element("advisor-budget").disabled = key == "video" and mode != "generate"
    has_tokens = units == "requests"
    element("advisor-volume-caption").textContent = (f"Monthly {units}" + (" (optional)" if key == "custom-output" else "")) if units else "Monthly workload"
    for name, visible in (("volume", bool(units)), ("input", has_tokens), ("output", has_tokens)):
        field = element(f"advisor-{name}")
        element(f"advisor-{name}-label").hidden = not visible
        field.disabled = not visible
        field.required = visible and not (name == "volume" and key == "custom-output")
        if has_tokens and name in ("input", "output") and not field.value:
            field.value = value("prompt" if name == "input" else "completion")


def advisor_candidates(task, provider, volume, input_tokens, output_tokens, query):
    candidates = []
    common = {"about", "from", "have", "help", "into", "model", "models", "need", "that", "their", "this", "using", "want", "what", "with", "would"}
    common.update({"search", "find", "output", "please", "provide", "should", "task", "require", "requirements", "produce"})
    def terms(text):
        return {word.removesuffix("s") for word in re.findall(r"[a-z0-9]{3,}", text.casefold()) if word not in common}

    keywords = terms(query)
    category_keywords = {
        "reranking": {"rerank", "reranking", "reranker"},
        "embedding": {"embedding", "embed", "vector"},
    }
    explicit_categories = {name for name, words in category_keywords.items() if keywords & words}

    def add(name, vendor, reason, source, score, monthly=None, basis="", key=""):
        if not provider or vendor.casefold() == provider:
            candidates.append((score, name, vendor, reason, source, monthly, basis, key))

    for name, reason, slug, rate, basis in ADVISOR_SERVICES.get(task, ()):
        add(name, "Amazon", reason, f"https://aws.amazon.com/{slug}/pricing/", 100,
            volume * rate if rate is not None else None, basis)

    for kind, rate, basis in ADVISOR_MEDIA.get(task, ()):
        for row in snapshot["media"]:
            if row["type"] == kind:
                add(row["model"], row["company"], row["domain"], row["source"], 80,
                    volume * rate, basis)

    shortlist = {
        row["id"]: (index, row)
        for index, row in enumerate(snapshot["shortlists"].get(ADVISOR_SHORTLISTS.get(task), ()))
    }
    category = ADVISOR_TASKS[task][3]
    for key, row in metadata.items():
        index, curated = shortlist.get(key, (0, {}))
        evidence = " ".join(str(item or "") for item in (
            row["name"], row.get("useCase"), row.get("domain"), curated.get("fit"), row["category"],
        ))
        overlap = len(keywords & terms(evidence))
        if task == "custom-output":
            eligible = row["category"] in explicit_categories if explicit_categories else overlap > 0
        elif task == "text":
            eligible = row["category"] in {"Text/chat", "chat", "Multimodal chat"} and not re.search(
                r"guard|moderation|safeguard", row["name"], re.I
            )
        elif task == "code":
            eligible = bool(curated) or bool(re.search(r"coder|coding|code generation|software engineering",
                                                     " ".join(row.get(field) or "" for field in ("name", "useCase", "domain")), re.I))
            eligible = eligible and row["category"] in {"Text/chat", "chat", "Multimodal chat"}
        elif task == "ocr":
            eligible = bool(re.search(r"ocr", row["name"], re.I))
        else:
            eligible = bool(category) and row["category"] == category
        if not eligible:
            continue
        model = catalog[key]
        cost = None
        basis = row.get("documentedRate") or ""
        if volume is not None and ADVISOR_TASKS[task][2] == "requests" and model.comparable:
            cost = volume * (input_tokens * model.input_rate + output_tokens * model.output_rate) / MILLION
            basis = f"{money(model.input_rate)} input / {money(model.output_rate)} output per 1M tokens"
        score = (65 - index if curated else 30) + min(overlap, 4) * 8
        add(row["name"], row["provider"], curated.get("fit") or row.get("useCase") or row["category"],
            row.get("source"), score, cost, basis, key)
    return candidates


def advisor_card(parent, candidate):
    _, name, vendor, reason, source, monthly, basis, key = candidate
    card = document.createElement("article")
    card.className = "advisor-result"
    parent.appendChild(card)
    for tag, content in (
        ("h4", f"{name} · {vendor}"),
        ("p", reason),
        ("p", f"Estimated USD / month: ${monthly:,.2f}" if monthly is not None else "Comparable monthly estimate unavailable"),
    ):
        node = document.createElement(tag)
        node.textContent = content
        card.appendChild(node)
    if basis:
        node = document.createElement("p")
        node.textContent = basis
        card.appendChild(node)
    if source and source.startswith("https://"):
        link = document.createElement("a")
        link.href = source
        link.target = "_blank"
        link.rel = "noopener noreferrer"
        link.textContent = "View source"
        card.appendChild(link)
    if key:
        button = document.createElement("button")
        button.type = "button"
        button.textContent = "Model details"
        button.setAttribute("data-model", key)
        button.setAttribute("data-action", "metadata")
        card.appendChild(button)


def recommend_video_editor():
    goal = value("advisor-edit-goal")
    if goal not in VIDEO_EDIT_TOOLS:
        advisor_message("Choose what you want to do with the footage.")
        return
    name, reason, source, pricing = VIDEO_EDIT_TOOLS[goal]
    fit = element("advisor-fit")
    fit.replaceChildren()
    provider = value("advisor-provider")
    vendor = "Runway" if goal == "objects" else name
    if not provider or provider == vendor.casefold():
        advisor_card(fit, (100, name, vendor, reason, source, None, "Check plan limits and billing for your workflow.", ""))
        link = document.createElement("a")
        link.href = pricing
        link.target = "_blank"
        link.rel = "noopener noreferrer"
        link.textContent = "View pricing plans"
        fit.appendChild(link)
    else:
        fit.textContent = "No editing tool in this shortlist matches the selected provider."
    element("advisor-cost").textContent = "Comparable editing cost estimates are unavailable. See the provider's pricing plans."
    element("advisor-summary").textContent = "Recommendations for editing existing footage."
    advisor_message("")
    element("advisor-results").hidden = False


def recommend_models(event):
    event.preventDefault()
    clear_advisor_results()
    task = advisor_task()
    detail = value("advisor-detail").strip()
    if value("advisor-task") == "custom-output" and not detail:
        advisor_message("Describe the output you need.")
        return
    if task not in ADVISOR_TASKS:
        advisor_message("Choose a required output.")
        return
    if task == "video":
        mode = value("advisor-video-mode")
        if mode == "edit":
            recommend_video_editor()
            return
        if mode != "generate":
            advisor_message("Choose whether to edit existing footage or generate new clips.")
            return
    followup = value("advisor-followup").strip()
    if not followup:
        advisor_message("Answer the follow-up question to get recommendations.")
        return
    if task == "clinical":
        advisor_message(
            "For disease detection, specify the indication and imaging modality with your clinical team. "
            "Evaluate a tool validated for that intended use and confirm its per-study price with the vendor."
        )
        return
    try:
        units = ADVISOR_TASKS[task][2]
        raw_volume = value("advisor-volume")
        volume = None if task == "custom-output" and not raw_volume else number(raw_volume, f"Monthly {units}")
        if volume is not None and volume <= 0:
            raise ValueError("Enter a monthly workload greater than zero.")
        use_tokens = units == "requests"
        input_tokens = number(value("advisor-input"), "Input tokens", whole=True) if use_tokens else 0
        output_tokens = number(value("advisor-output"), "Output tokens", whole=True) if use_tokens else 0
        if use_tokens and not input_tokens + output_tokens:
            raise ValueError("Enter at least one input or output token per request.")
        budget = number(value("advisor-budget"), "Monthly budget") if value("advisor-budget") else None
    except ValueError as error:
        advisor_message(str(error))
        return
    query = detail if task == "custom-output" else f'{value("advisor-query")} {detail}'
    candidates = advisor_candidates(task, value("advisor-provider"), volume, input_tokens, output_tokens, f"{query} {followup}")
    fit = sorted(candidates, key=lambda row: (-row[0], row[1].casefold()))
    priced = sorted(
        (row for row in candidates if row[5] is not None and (budget is None or row[5] <= budget)),
        key=lambda row: (row[5], -row[0], row[1].casefold()),
    )
    for target, rows, empty in (
        ("advisor-fit", fit, "No catalog candidates match the output and provider."),
        ("advisor-cost", priced, "Enter a monthly workload to estimate costs." if volume is None and fit else
         "No candidates with comparable prices meet the selected requirements and budget."),
    ):
        parent = element(target)
        parent.replaceChildren()
        if not rows:
            parent.textContent = empty
        for row in rows[:3]:
            advisor_card(parent, row)
    element("advisor-summary").textContent = (
        (f"Estimates for {volume:,} {units} per month. " if volume is not None else "")
        + ("Custom results match words in catalog descriptions. Verify that each model meets your requirements. "
           if task == "custom-output" else "Best fit uses documented capabilities and curated catalog notes. Validate quality on your data. ")
        + "The budget applies to cost-competitive results."
    )
    advisor_message("")
    element("advisor-results").hidden = False


